    return all(char in iter_s for char in t)

def find_journey_length(s):
    """Find the maximum length of a journey on string s."""
    max_length = 1  # Minimum length is 1 as there's at least one string in any journey.
    for i in range(1, len(s) - 1):
        for subseq in permutations(range(i + 1), len(s) - i):
            if is_subsequence(s[i:], ''.join([s[j] for j in subseq])):
                max_length = max(max_length, len(str(subseq)))
