import sys
from collections import defaultdict

def dijkstra(graph, start):
    from heapq import heappop, heappush
    distances = {vertex: float('inf') for vertex in graph}
    distances[start] = 0
    priority_queue = [(0, start)]
    while priority_queue:
        current_distance, current_vertex = heappop(priority_queue)
        if current_distance > distances[current_vertex]:
            continue
        for neighbor, weight in graph[current_vertex].items():
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))
    return distances

def find_min_cost(kruskal_diameter, leaf_counts):
    cost = 0
    vertices = set(range(1, len(leaf_counts) + 1))
    kruskal_count = len(leaf_counts) // 2
    cost += kruskal_diameter * kruskal_count
    for i in range(kruskal_count):
        if len(leaf_counts) % 2 == 0:
            cost += 2 * leaf_counts[2 * i] * 2
