from collections import defaultdict

class RoadNetwork:
    def __init__(self, n, m, roads):
        self.graph = defaultdict(list)
        self.snow_tree = []
        for a, b in roads:
            self.graph[a].append(b)
            self.graph[b].append(a)
        for i in range(1, m + 1):
            self.snow_tree.append((i, i))

    def shortest_path(self, start, end):
        dist = {start: 0}
        path = {}
        q = [start]

        while q:
            u = q.pop()
            for v in self.graph[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    path[v] = u
                    if v in [i[1] for i in self.snow_tree]:
                        self.snow_tree.remove((v, u))
                        if v == end:
                            break
                    q.append(v)
                    # Break when there exist i-th or later trees in snow trees
                    if not self.snow_tree:
                        break
        # In case there are multiple ways back to start, pick the first one
        if dist[end] > 1:
            od = [(d, u) for u, d in path.items()]
            od.sort()
            return dist[od[0][1]]
        return dist[end]

