import sys
from heapq import heappush, heappop

class RoadNetwork:
    def __init__(self, n, m, roads):
        self.adj = [[] for _ in range(n)]
        for i, (u, v) in enumerate(roads):
            self.adj[u-1].append((i+1, v-1))
            self.adj[v-1].append((i+1, u-1))
        self.indegree = [0] * n
        for i in range(n):
            self.indegree[i] = len(self.adj[i])
        assert(sum(self.indegree) == m)

    def dijkstra(self, start, goal, time_limit):
        n = len(self.adj)
        distances = [float('inf')] * n
        distances[start-1] = 0
        pq = [(0, start-1)]
        while pq:
            cur_dist, cur_i = heappop(pq)
            if cur_dist > distances[cur_i]:
                continue
            if cur_i == goal-1 and cur_dist <= time_limit:
                return True
            for next, next_i in self.adj[cur_i]:
                dist = cur_dist + next
                if dist < distances[next_i]:
                    distances[next_i] = dist
                    heappush(pq, (dist, next_i))
        return False

def solve():
    n, m, q = map(int, input().split())
    roads = [tuple(map(int, input().split())) for _ in range(m)]
    network = RoadNetwork(n, m, roads)
    for _ in range(q):
        l, r, s, t = map(int, input().split())
        if network.dijkstra(s-1, t-1, r):
            print("Yes")
        else:
            print("No")

if __name__ == "__main__":
    sys.stdin = open("input.txt", "r")
    solve()
