def find_special_vertex(tree):
    if not tree:
        return None

    depth = [0] * (len(tree) + 1)

    def query(u, v):
        nonlocal depth
        depth[u] += 1
        depth[v] += 1
        return max(depth[u], depth[v] - 1)

    def dfs(u, parent):
        for v in tree[u]:
            if v != parent:
                depth[v] = query(u, v)
                dfs(v, u)

    dfs(0, -1)
    for i in range(1, len(tree) + 1):
        if depth[1] - depth[i] == 1:
            return i
        depth[i] = query(i, 1)

    return None

