from typing import List

def lexicographically_smallest_B(N: int, K: int, A: List[int]) -> List[int]:
    B = A.copy()
    non_decreasing_subsequence = [0] * N
    for i in range(N - 1, -1, -1):
        for j in range(i + 1, N):
            if A[j] >= A[i] and non_decreasing_subsequence[j] < non_decreasing_subsequence[i] + 1:
                non_decreasing_subsequence[j] = non_decreasing_subsequence[i] + 1
        for j in range(i):
            if A[j] >= A[i] and non_decreasing_subsequence[j] == non_decreasing_subsequence[i] + 1:
                return -1
    if max(non_decreasing_subsequence) < K:
        return -1
    return B[:K]

