class BinaryStringMerger:
    def __init__(self, t):
        self.t = t
        self.successors = self.make_successors()

    def make_successors(self):
        successors = {}
        for i in range(len(self.t) - 1):
            successors.setdefault(self.t[i:i+3], set())
            successors[self.t[i:i+3]].add(self.t[i+1:i+3])
        return [successors[key] if len(successors[key]) > 0 else [successors[key]] for key in successors]

    def swap_handler(self, code):
        code_set = set()
        last_index = -1
        for s in self.successors[code]:
            if code == '011' and s == '101': 
                s = '110'
            if s in ('110', '011'): 
                continue
            code_set.add(s)
            last_index = len(code_set) - 1
        return code_set, last_index

    def is_nearly_reachable(self, codet1, codet2, len_opt):
        codet2, last_index = self.swap_handler(codet2)
        right_bound = len_opt
        while len(codet1) <= right_bound:
            codet2_set, codet2_last_index = self.swap_handler(codet2)
            candidates_to_add = {}
            for candidate in codet2_set:
                if len(self.successors[candidate]) >= len_opt - right_bound:
                    candidates_to_add[candidate] = True
            if codet2_last_index + len_opt <= len(codet2):
                next_candidate = codet2[codet2_last_index + len_opt:right_bound + 1]
                candidates_to_add[next_candidate] = True
            if candidates_to_add:
                codet1, right_index = self.swap_handler(codet1)
                right_bound = right_index + len_opt
            else:
                return 'No'
        return 'Yes'

    def is_reachable(self, l1first, l1second, l2first, len_opt):
        return self.is_nearly_reachable(self.t[l1first - 1:l1second], self.t[l2first - 1:l2second], len_opt)


