import sys

def find_replace_num(num1, num2):
    if num1 == '11' or num2 == '11':
        return '011'
    if num1 == '011' or num2 == '011':
        return '110'
    if num1 == '01' and num2 == '01':
        return '11'
    if num1 == '11' and num2 == '01':
        return '10'
    if num1 == '10' and num2 == '11':
        return '01'
    if num1 == '01' and num2 == '11':
        return '11'

def is_reachable(s1, s2):
    if s1 == s2:
        return True
    if s1 == '011':
        return s2 in ['110', '011']
    if s2 == '110':
        return s1 in ['110', '011']
    return False

def solution(length, t, queries):
    results = []
    for query in queries:
        l1, l2, len_query = query
        s1 = t[l1-1:l1+len_query]
        s2 = t[l2-1:l2+len_query]
        if l1 <= l2 and s2 == '011':
            changed = s1.replace('111', find_replace_num(s2[0], s2[2]))
            if is_reachable(s1, s2) and len(s1) > len(s2):
                results.append('Yes')
            elif is_reachable(changed, s2) and len(changed) > len(s2):
                results.append('Yes')
            else:
                results.append('No')
        elif l1 >= l2 and s2 == '110':
            changed = s1.replace('010', find_replace_num(s2[0], s2[2]))
            if is_reachable(s1, s2) and len(s1) > len(s2):
                results.append('Yes')
            elif is_reachable(changed, s2) and len(changed) > len(s2):
                results.append('Yes')
            else:
                results.append('No')
        else:
            results.append('No')
    return results

if __name__ == "__main__":
    input = sys.stdin.read
    data = str(input().strip())
    data = data.split('\n')
    length = int(data[0])
    string = data[1]
    q = int(data[2])
    queries = []
    for _ in range(q):
        query = list(map(int, input().strip().split()))
        queries.append((query[0], query[1], query[2]))
    results = solution(length, string, queries)
    for result in results:
        print(result)
