def process_traffic_jams(days_passed, segment_period):
    current_time = 0
    for city in range(1, segment_period):
        if days_passed % city == 0:
            current_time += 1
    return current_time


def process_queries(q, queries):
    queries_processed = 0
    for query in queries:
        if query.startswith('A'):
            city1, city2 = map(int, query[2:].split())
            days_passed = process_traffic_jams(current_time, segment_period[city1-1])
            resulting_time = city1 + days_passed
            current_time = resulting_time
        else:
            x, value = map(int, query[2:].split())
            segment_period[x-1] = value
    return current_time


def main():
    n = int(input())
    segment_periods = list(map(int, input().split()))
    q = int(input())
    initial_time = 0
