def count_winning_arrays(n, elements):
    MOD = 10**9 + 7
    dp = [[0, 0, 0, 0] for _ in range(n)]
    dp[0] = [1, 0, 1, 0]

    for i in range(1, n):
        for j in range(4):
            if j == 0:
                dp[i][0] = (dp[i-1][0] + dp[i-1][1]) % MOD
            elif j == 1:
                dp[i][1] = ((dp[i-1][0] + dp[i-1][1]) % MOD + dp[i-1][2]) % MOD
            elif j == 2:
                dp[i][2] = (dp[i-1][1] + (2 * dp[i-1][2] + 1) % MOD) % MOD
            else:
                dp[i][3] = ((dp[i-1][2] + (2 * dp[i-1][3] + 1) % MOD + mod(2)) % MOD + mod(2)) % MOD

    return sum(dp[n-1][j] for j in range(4)) % MOD

def mod(number):
    return number if 0 <= number < MOD else number - MOD

n = int(input())
